var n=`0011-banosh`;var t=`world-0011`;var a=`UA`;var s=`eastern-europe`;var r=4;var o=30;var g={en:`Banosh`,ua:`Банош`};var m={en:`A classic dish from Ukraine, featuring heavy cream, corn grits, bryndza, bacon. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: вершки високої жирності, кукурудзяна крупа, бринза, бекон. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 5 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 5 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:5,i:[[`heavy-cream`,500,`ml`],[`water`,250,`ml`],[`table-salt`,3,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 20 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 20 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:20,i:[[`corn-grits`,170,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`bryndza`,180,`g`],[`unsalted-butter`,35,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`bacon`,110,`g`]]}];var d={slug:n,id:t,country:`UA`,region:s,servings:4,minutes:30,title:g,text:m,steps:h};export{a as country,d as default,t as id,o as minutes,s as region,r as servings,n as slug,h as steps,m as text,g as title};